// Package web holds the HTTP handlers and the templates they render.
package web

import (
	"embed"
	"html/template"
	"io/fs"
	"log/slog"
	"net/http"
)

// static/app.css is generated by `make css` from styles.css; it is embedded when present.
//
//go:embed static templates
var files embed.FS

// NewHandler returns the application's HTTP handler.
func NewHandler() http.Handler {
	home := template.Must(template.ParseFS(files, "templates/layout.html", "templates/home.html"))
	static, err := fs.Sub(files, "static")
	if err != nil {
		panic(err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("ok"))
	})
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServerFS(static)))
	mux.HandleFunc("GET /{$}", func(w http.ResponseWriter, _ *http.Request) {
		if err := home.ExecuteTemplate(w, "layout", nil); err != nil {
			slog.Error("render home", "err", err)
		}
	})
	return mux
}
